rzz(-gamma) q[3], q[7];
rzz(-gamma) q[3], q[5];
rzz(-gamma) q[7], q[5];
rzz(-gamma) q[5], q[6];
rx(2*beta) q[0];
rx(2*beta) q[1];
rx(2*beta) q[2];
rx(2*beta) q[3];
rx(2*beta) q[4];
rx(2*beta) q[5];
rx(2*beta) q[6];
rx(2*beta) q[7];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
measure q[3] -> c[3];
measure q[4] -> c[4];
measure q[5] -> c[5];
measure q[6] -> c[6];
measure q[7] -> c[7];"""

code_string = """from qiskit import transpile
from scipy.optimize import minimize

def run_and_analyze(circuit, aer_sim, graph):
    transpiled_circuit = transpile(circuit, aer_sim)

    def objective(params):
        param_binds = [{circuit.parameters[0]: [params[0]], circuit.parameters[1]: [params[1]]}]
        job = aer_sim.run(transpiled_circuit, parameter_binds=param_binds, shots=4096)
        counts_list = job.result().get_counts()
        counts = counts_list[0]
        expectation = compute_expectation(counts, graph)
        return -expectation

    initial_params = [0.1] * circuit.num_parameters
    result = minimize(objective, initial_params, method='Nelder-Mead')
    opt_params = result.x

    param_binds = [{circuit.parameters[0]: [opt_params[0]], circuit.parameters[1]: [opt_params[1]]}]
    job = aer_sim.run(transpiled_circuit, parameter_binds=param_binds, shots=4096)
    counts = job.result().get_counts()[0]

    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    top_two = [bitstring for bitstring, count in sorted_counts[:2]]
    return top_two"""
